package com.example.techfix;
import android.content.Intent; import android.os.*; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; import androidx.recyclerview.widget.*; import com.example.techfix.data.AppDatabase; import com.example.techfix.data.entity.RepairService; import com.example.techfix.ui.ServiceAdapter; import java.util.concurrent.*; import java.util.*;
public class ServicesActivity extends AppCompatActivity {private final ExecutorService executor=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_services);int categoryId=getIntent().getIntExtra("CATEGORY_ID",-1);String name=getIntent().getStringExtra("CATEGORY_NAME");if(name==null)name="Services";int userId=getIntent().getIntExtra("USER_ID",-1);((TextView)findViewById(R.id.tvCategoryTitle)).setText(name);RecyclerView rv=findViewById(R.id.rvServices);rv.setLayoutManager(new LinearLayoutManager(this));AppDatabase db=AppDatabase.getDatabase(getApplicationContext());executor.execute(()->{List<RepairService> services=db.repairServiceDao().getServicesByCategory(categoryId);main.post(()->rv.setAdapter(new ServiceAdapter(services,s->{Intent i=new Intent(this,BookingActivity.class);i.putExtra("SERVICE_ID",s.getServiceId());i.putExtra("SERVICE_NAME",s.getName());i.putExtra("SERVICE_PRICE",s.getPrice());i.putExtra("CUSTOMER_ID",userId);startActivity(i);})));});} @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}}
